	@Test
	void independentOptionalOrdersCompeteWithoutLosingDuplicateOrUnmatchedRows() {
		TupleExpr source = new LeftJoin(new LeftJoin(values("x", "a", "a", "missing"),
				pattern("x", "b", "y")), pattern("x", "c", "z"));
		Model data = model();
		add(data, "a", "b", iri("b1"));
		add(data, "a", "b", iri("b2"));
		add(data, "a", "c", iri("c1"));
		List<String> expected = List.of("x=urn:t:a|y=urn:t:b1|z=urn:t:c1",
				"x=urn:t:a|y=urn:t:b1|z=urn:t:c1", "x=urn:t:a|y=urn:t:b2|z=urn:t:c1",
				"x=urn:t:a|y=urn:t:b2|z=urn:t:c1", "x=urn:t:missing");
		assertEquals(expected, evaluate(data, source));

		PackedQuery packed = encode(source);
		assertTrue(hasOptionalOrder(packed, "b", "c"), "the source order must remain a competing alternative");
		assertTrue(hasOptionalOrder(packed, "c", "b"),
				"independent OPTIONAL branches must have a second order in the same semantic group");
		assertRootAlternativesPreserveBag(data, source, packed);
	}

