	@Test
	void parsedOptionalGroupScopesRemainIntactWhileTheirOrdersCompete() {
		TupleExpr source = parse("""
				SELECT * WHERE {
				  VALUES ?x { :a :a :missing }
				  OPTIONAL { ?x :b ?y }
				  OPTIONAL { ?x :c ?z }
				}
				""");
		Model data = model();
		add(data, "a", "b", iri("b1"));
		add(data, "a", "c", iri("c1"));
		PackedQuery packed = encode(source);
		int optional = optionalRoot(packed);
		int originalScope = packed.relSemanticScope(packed.relChild(optional, 1));
		assertTrue(hasOptionalOrder(packed, "b", "c"));
		assertTrue(hasOptionalOrder(packed, "c", "b"),
				"moving an intact pure OPTIONAL group must not require erasing its parser scope");
		for (int id : rootAlternatives(packed)) {
			int inner = packed.relChild(id, 0);
			if (packed.relOperator(inner) == PackedRelOp.LEFT_JOIN
					&& containsPredicate(packed, packed.relChild(inner, 1), "c")) {
				assertEquals(originalScope, packed.relSemanticScope(packed.relChild(inner, 1)));
			}
		}
		assertRootAlternativesPreserveBag(data, source, packed);
	}

