	@Test
	void parsedOptionalWinnerFollowsCostsInBothDirections() {
		TupleExpr source = parse("""
				SELECT * WHERE {
				  VALUES ?x { :a :a :missing }
				  OPTIONAL { ?x :b ?y }
				  OPTIONAL { ?x :c ?z }
				}
				""");
		Model data = model();
		add(data, "a", "b", iri("b1"));
		add(data, "a", "c", iri("c1"));
		for (String preferredOuter : List.of("b", "c")) {
			TupleExpr selected = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(),
					costsPreferringOuter(preferredOuter)).selectedPlan();
			LeftJoin optional = firstOptional(selected);
			assertNotNull(optional);
			StatementPattern right = assertInstanceOf(StatementPattern.class, optional.getRightArg());
			assertEquals(iri(preferredOuter), right.getPredicateVar().getValue(), selected::toString);
			assertEquals(evaluate(data, source), evaluate(data, selected));
		}
	}

