	@Test
	void theCostModelCanSelectEitherOriginalOrInjectedOptionalBody() {
		TupleExpr source = new LeftJoin(fixedGraphPattern("x", "base", "a"),
				fixedGraphPattern("x", "detail", "d"));
		PlanningGraphDomains.capture(source, PlanningGraphDomain.defaultGraph());
		Model data = model();
		data.add(iri("a"), iri("base"), iri("a1"), iri("graph"));
		data.add(iri("a"), iri("base"), iri("a2"), iri("graph"));
		data.add(iri("a"), iri("detail"), iri("d1"), iri("graph"));
		data.add(iri("missing"), iri("base"), iri("a3"), iri("graph"));
		for (boolean preferInjection : List.of(false, true)) {
			boolean[] costedBodies = new boolean[2];
			boolean[] costedPhysicalBodies = new boolean[2];
			PackedCostModel costs = new PackedCostModel() {
				@Override
				public double estimateRows(PackedQueryView query, int relationId) {
					return query.isStatementPattern(relationId) ? 10.0d : Double.NaN;
				}

				@Override
				public PackedCostSession openSession(PackedQueryView query) {
					return new PackedCostSession() {
						@Override
						public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
							output.setRows(10.0d, 10.0d);
							output.setEvidenceStateId(0);
						}

						@Override
						public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
							estimateLeaf(relationId, context, output);
						}

						@Override
						public void refineOperator(int relationId, PackedCostContext context,
								PackedCostEstimate output) {
							if (query.operatorTag(relationId) == PackedRelOp.LEFT_JOIN) {
								boolean injected = query
										.operatorTag(query.childRelationId(relationId, 1)) == PackedRelOp.JOIN;
								costedBodies[injected ? 1 : 0] = true;
								output.setEvidenceStateId(injected ? 2 : 1);
								priceOptional(output, injected);
							} else {
								output.setEvidenceStateId(0);
							}
						}

						@Override
						public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
							// OPTIONAL's hash and memo implementations receive their concrete prices after the
							// logical event. Carry its evidence into that event so every implementation is priced.
							if (context.hasPhysicalJoinRefinement() && output.evidenceStateId() != 0) {
								boolean injected = output.evidenceStateId() == 2;
								costedPhysicalBodies[injected ? 1 : 0] = true;
								priceOptional(output, injected);
							}
						}

						private void priceOptional(PackedCostEstimate output, boolean injected) {
							output.setLocalPhysicalCost(injected == preferInjection ? 1.0d : 1_000_000.0d,
									0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
						}
					};
				}
			};
			TupleExpr selected = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), costs)
					.selectedPlan();
			assertTrue(costedBodies[0] && costedBodies[1], "both equivalent OPTIONAL bodies must reach costing");
			assertTrue(costedPhysicalBodies[0] && costedPhysicalBodies[1],
					"both OPTIONAL body prices must reach their concrete physical join implementations");
			LeftJoin optional = assertInstanceOf(LeftJoin.class, selected);
			assertEquals(preferInjection, optional.getRightArg() instanceof Join, selected::toString);
			assertEquals(evaluate(data, source), evaluate(data, selected));
		}
	}

